with base as (select *, case when job_title in ('Designer', 'Analyst') then 'Tier 1' else 'Other' end as job_title_group, coalesce(level, 'NONE') as level_filled from employees where hire_date > date '2023-08-12'), latest as (select *, row_number() over (partition by dept_id order by hire_date desc nulls last, id) as latest_rank from base qualify latest_rank = 1), filtered as (select id, full_name, email, dept_id, manager_id, job_title, salary, hire_date, is_remote, level, job_title_group, level_filled, latest_rank, greatest(salary, latest_rank) as greatest_salary_latest_rank, case when level in ('L1', 'L4') then 'Tier 1' else 'Other' end as level_group, coalesce(job_title, 'NONE') as job_title_filled from latest where manager_id = 9), latest_employees as (select id, dept_id, manager_id, job_title, latest_rank, greatest_salary_latest_rank, level_group from (select *, row_number() over (partition by manager_id order by greatest_salary_latest_rank desc nulls first, id) as rank_in_group from filtered) t where rank_in_group = 1), enriched as (select e.*, p.email from latest_employees e inner join employees p on e.manager_id = p.id), joined as (select src.id, src.manager_id, src.latest_rank, src.level_group, src.email, e.hire_date, e.salary from enriched src left join employees e on src.manager_id = e.id), scored as (select id, latest_rank, level_group, email, hire_date, dense_rank() over (order by salary desc) as salary_dense_rank, round(salary / sum(salary) over (partition by manager_id), 4) as salary_share from joined where latest_rank <= 1) select id, latest_rank, level_group, hire_date, salary_share, lead(salary_dense_rank) over w_hist as next_salary_dense_rank, lag(salary_dense_rank) over w_hist as prev_salary_dense_rank, lead(salary_share) over w_hist as next_salary_share, row_number() over w_hist as event_seq from scored window w_hist as (order by salary_dense_rank, id)
